```
import { DateRangeField } from "@ingradient/ui";

const Default = () => <Demo />;
```

### With Value

Story ID: patterns-forms-daterangefield--with-value

```
import { DateRangeField } from "@ingradient/ui";

const WithValue = () => <DateRangeField from="2024-12-01" to="2024-12-31" onChange={() => undefined} />;
```

